class PolicyAuthority:
    ...
    def publish_case_counts(self, day: int, external_series: Optional[list], people: list) -> None:
        value = None
        if external_series and 0 <= day < len(external_series):
            value = float(external_series[day])
        # Fallback to internal prevalence if not provided
        # The caller should pass current prevalence if external is None
        for person in people:
            person.perceived_local_cases = value if value is not None else person.perceived_local_cases

    def adjust_messaging(self, people: list, intensity: float) -> None:
        for person in people:
            k = float(intensity) * person.trust_in_authorities
            # Nudge risk perception toward perceived cases
            if hasattr(person, 'perceived_local_cases') and person.perceived_local_cases is not None:
                person.risk_perception = max(0.0, min(1.0, (1 - k) * person.risk_perception + k * person.perceived_local_cases))

