    def admit_agents(self, agent_ids: list) -> list:
        return agent_ids[: self.capacity]

    def enforce_policy(self, rng, people: list) -> tuple:
        fines = 0; denied = 0
        for pid in people:
            p = people[pid]
            if self.mask_requirement and p.mask_adoption_state != 'wearing':
                if rng.random() < self.enforcement_probability:
                    if rng.random() < 0.5:
                        fines += self.fine_amount
                    else:
                        denied += 1
        return fines, denied

